// Focus, "Frutiger Aero" look: a photographed beach at night-into-day, each self-care need a thing in it whose frames
// run from just-done to due. Everything about the look (art, placement, touch boxes) is in aeroLook.js, generated by
// tools/aero/build.py; this file only knows how to show any thing and how it answers touch.
import { useEffect, useMemo, useRef, useState } from "react";
import { Animated, Easing, Image, PanResponder, Platform, Pressable, StyleSheet, Text, View, useWindowDimensions } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { fmtTime } from "../model";
import { AERO_LOOK as LOOK } from "./aeroLook";

const dur = (ms) => { const m = Math.round(ms / 6e4); return m >= 60 ? Math.floor(m / 60) + "h" + (m % 60 ? " " + (m % 60) + "m" : "") : m + "m"; };

export default function AeroFocus({ needs, left, onPlay, onEnd, look, looks, setLook }) {
  const ins = useSafeAreaInsets();
  const { width: W, height: H } = useWindowDimensions();
  // Fill the screen with the tall plate; on 19.5:9 phones the full width shows, on shorter ones a bit of sky/sand trims.
  const s = Math.max(W / LOOK.plate[0], H / LOOK.plate[1]);
  const ox = (W - LOOK.size[0] * s) / 2, oy = (H - LOOK.plate[1] * s) / 2 + LOOK.plateTop * s;
  const by = Object.fromEntries(needs.map((n) => [n.key, n]));
  const [info, setInfo] = useState(null); // { key, done }: the full-info card after a swipe
  const [showLooks, setShowLooks] = useState(false);
  const infoT = useRef(null);
  const onInfo = (n, done) => { setInfo({ key: n.key, done }); clearTimeout(infoT.current); infoT.current = setTimeout(() => setInfo(null), done ? 2600 : 5000); };
  useEffect(() => () => clearTimeout(infoT.current), []);
  const iN = info && by[info.key];
  const place = (b) => ({ position: "absolute", left: ox + b.x * s, top: oy + b.y * s, width: b.w * s, height: b.h * s });
  return (
    <View style={{ flex: 1, backgroundColor: "#0b86e6", overflow: "hidden" }}>
      <Image source={LOOK.bg} style={{ position: "absolute", left: ox, top: oy - LOOK.plateTop * s, width: LOOK.plate[0] * s, height: LOOK.plate[1] * s }} />
      {/* ambient life: retro GIF loops over the photo (stars twinkling in the Milky Way, glints along the water stream) */}
      {Object.entries(LOOK.life).map(([k, b]) => <Image key={k} source={b.src} fadeDuration={0} pointerEvents="none" style={place(b)} />)}
      {LOOK.order.filter((k) => by[k]).map((k, i) => <Thing key={k} k={k} n={by[k]} i={i} s={s} ox={ox} oy={oy} left={left(by[k])} onPlay={onPlay} onInfo={onInfo} />)}
      <Pressable onPress={onEnd} onLongPress={() => setShowLooks((v) => !v)} style={[st.end, { top: ins.top + 10, zIndex: 60 }]} accessibilityRole="button" accessibilityLabel="End focus" accessibilityHint="Hold to choose a look" hitSlop={10}>
        <Text style={st.endTxt}>End</Text>
      </Pressable>
      {iN && (
        <Pressable onPress={() => setInfo(null)} style={[st.info, { top: ins.top + 14, zIndex: 55 }]} accessibilityLiveRegion="polite">
          <Text style={st.infoTitle} numberOfLines={1}>{iN.card.label}</Text>
          {info.done
            ? <Text style={st.infoLine}>Done · next in about {dur(iN.every)}</Text>
            : <>
              <Text style={st.infoLine}>{iN.fill >= 1 ? "Due now" : "Due in " + left(iN)} · every {dur(iN.every)}</Text>
              <Text style={st.infoLine}>Counting from {fmtTime(new Date(iN.last))} · {Math.min(100, Math.round(iN.fill * 100))}% there</Text>
              <Text style={st.infoHint}>Swipe it up when you've done it</Text>
            </>}
        </Pressable>
      )}
      {showLooks && <View style={[st.looks, { bottom: ins.bottom + 14, zIndex: 60 }]}>
        <Text style={st.sub}>LOOK</Text>
        {looks.map(([k, l]) => (
          <Pressable key={k} onPress={() => setLook(k)} style={[st.chip, k === look && st.chipOn]} accessibilityRole="radio" accessibilityState={{ selected: k === look }}>
            <Text style={[st.chipTxt, k === look && { color: "#ffffff" }]}>{l}</Text>
          </Pressable>
        ))}
      </View>}
    </View>
  );
}

/** One need in the scene: its frame shows how due it is. Hold for the time left, swipe up when done, down for details.
 *  Nothing slides under your finger except a thing marked `lift` (the dolphin); the others run their frames back. */
function Thing({ k, n, i, s, ox, oy, left, onPlay, onInfo }) {
  const T = LOOK.things[k], R = T.rect, seq = T.frames, nF = seq.length;
  const [cleared, setCleared] = useState(false);
  useEffect(() => { setCleared(false); }, [Math.round(n.last / 1000)]);
  const pct = cleared ? 0 : Math.min(100, n.fill * 100);
  const full = !cleared && n.fill >= 1;
  const bob = useRef(new Animated.Value(0)).current, lift = useRef(new Animated.Value(0)).current;
  const pulse = useRef(new Animated.Value(0)).current, flash = useRef(new Animated.Value(0)).current;
  const rise = useRef(new Animated.Value(0)).current; // `rise`: climbs this far (scene px) as it comes due
  useEffect(() => { if (T.rise) Animated.timing(rise, { toValue: T.rise * pct / 100, duration: cleared ? 900 : 600, easing: Easing.inOut(Easing.cubic), useNativeDriver: true }).start(); }, [pct, cleared]);
  // Frames: jump to the target as time passes; after a swipe, run back down to frame 0.
  const target = Math.round(pct / 100 * (nF - 1));
  const [idx, setIdx] = useState(target), [shown, setShown] = useState(target);
  useEffect(() => {
    if (idx === target) return;
    if (!cleared) { setIdx(target); return; }
    const t = setTimeout(() => setIdx((j) => Math.max(target, j - Math.ceil(nF / 16))), 60); // about a second, however many frames return () => clearTimeout(t);
  }, [idx, target, cleared]);
  useEffect(() => {
    if (!T.bob) return;
    const d = T.sway ? 3600 : 2400 + i * 500;
    const a = Animated.loop(Animated.sequence([Animated.timing(bob, { toValue: 1, duration: d, easing: Easing.inOut(Easing.sin), useNativeDriver: true }), Animated.timing(bob, { toValue: 0, duration: d, easing: Easing.inOut(Easing.sin), useNativeDriver: true })]));
    a.start(); return () => a.stop();
  }, []);
  useEffect(() => {
    if (!full) { pulse.setValue(0); return; }
    const l = Animated.loop(Animated.sequence([Animated.timing(pulse, { toValue: 1, duration: 650, useNativeDriver: true }), Animated.timing(pulse, { toValue: 0, duration: 650, useNativeDriver: true })]));
    l.start(); return () => l.stop();
  }, [full]);
  const live = useRef({}); live.current = { onPlay, onInfo, n };
  const [peek, setPeek] = useState(false);
  const holdT = useRef(null), peekT = useRef(null);
  useEffect(() => () => { clearTimeout(holdT.current); clearTimeout(peekT.current); }, []);
  const done = () => {
    if (T.lift) Animated.sequence([Animated.timing(lift, { toValue: -60, duration: 160, useNativeDriver: true }), Animated.spring(lift, { toValue: 0, friction: 4, useNativeDriver: true })]).start();
    Animated.sequence([Animated.timing(flash, { toValue: 1, duration: 140, useNativeDriver: true }), Animated.timing(flash, { toValue: 0, duration: 700, easing: Easing.out(Easing.quad), useNativeDriver: true })]).start();
    setPeek(false); setCleared(true); live.current.onInfo(live.current.n, true); live.current.onPlay(live.current.n);
  };
  const pr = useMemo(() => {
    const endPeek = () => { clearTimeout(holdT.current); clearTimeout(peekT.current); peekT.current = setTimeout(() => setPeek(false), 1400); };
    const settle = () => { if (T.lift) Animated.spring(lift, { toValue: 0, useNativeDriver: true }).start(); };
    return PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderTerminationRequest: () => false,
      onPanResponderGrant: () => { clearTimeout(peekT.current); holdT.current = setTimeout(() => setPeek(true), 300); },
      onPanResponderMove: (_, g) => { if (Math.abs(g.dx) + Math.abs(g.dy) > 14) clearTimeout(holdT.current); if (T.lift) lift.setValue(Math.min(0, g.dy) * 0.6); },
      onPanResponderRelease: (_, g) => {
        endPeek();
        if (g.dy < -50) done();
        else { settle(); if (g.dy > 50) { setPeek(false); live.current.onInfo(live.current.n, false); } }
      },
      onPanResponderTerminate: () => { endPeek(); settle(); },
    });
  }, []);
  const x = ox + R.x * s, y = oy + R.y * s, w = R.w * s, h = R.h * s;
  // Touch box: the visible object in the current frame (plus a little padding), never the whole transparent image.
  const hb = T.hit[Math.min(idx, T.hit.length - 1)], pad = 8;
  let hx = x + hb[0] * w - pad, hy = y + hb[1] * h - pad, hw = hb[2] * w + pad * 2, hh = hb[3] * h + pad * 2;
  if (hw < 52) { hx -= (52 - hw) / 2; hw = 52; } if (hh < 52) { hy -= (52 - hh) / 2; hh = 52; }
  const climb = Animated.multiply(rise, -s), follow = T.rise ? [{ translateY: climb }] : [];
  const g = LOOK.glowPad;
  const spark = (() => { const [cx, cy, kk] = T.spark, d = Math.max(w, h) * kk; return { position: "absolute", left: w * cx - d / 2, top: h * cy - d / 2, width: d, height: d }; })();
  return (<>
    <Animated.View pointerEvents="none"
      style={{ position: "absolute", zIndex: 1 + i, left: x, top: y, width: w, height: h,
        transform: [{ translateY: Animated.add(Animated.add(lift, climb), bob.interpolate({ inputRange: [0, 1], outputRange: [-(T.bob || 0), T.bob || 0] })) },
          { rotate: bob.interpolate({ inputRange: [0, 1], outputRange: T.sway ? [-T.sway + "deg", T.sway + "deg"] : ["0deg", "0deg"] }) }] }}>
      {/* a halo that pulses while due and flashes when swiped done */}
      <Animated.Image source={T.glow} fadeDuration={0} style={{ position: "absolute", left: -w * g, top: -h * g, width: w * (1 + 2 * g), height: h * (1 + 2 * g),
        opacity: full ? pulse.interpolate({ inputRange: [0, 1], outputRange: [0.35, 0.75] }) : flash }} />
      {/* the last frame that finished loading stays underneath, so swapping frames never blinks */}
      <Image source={seq[shown]} fadeDuration={0} style={{ position: "absolute", left: 0, top: 0, width: w, height: h }} />
      <Image key={idx} source={seq[idx]} fadeDuration={0} onLoad={() => setShown(idx)} style={{ width: w, height: h }} />
      {full && <Image source={LOOK.sparkle} fadeDuration={0} style={spark} />}
    </Animated.View>
    <Animated.View {...pr.panHandlers} accessible accessibilityRole="button" accessibilityLabel={n.card.label + (full ? ", due now" : ", due in " + left)}
      accessibilityHint="Hold for the time left. Swipe up when done, swipe down for details."
      accessibilityActions={[{ name: "activate", label: "Mark done" }]} onAccessibilityAction={done}
      style={{ position: "absolute", zIndex: 20 + LOOK.touch.indexOf(k), left: hx, top: hy, width: hw, height: hh, transform: follow }} />
    {peek && (
      <Animated.View pointerEvents="none" style={[st.label, { position: "absolute", zIndex: 50, left: hx + hw / 2 - 40, width: 80, top: Math.max(hy - 34, 8), alignItems: "center", transform: follow }, full && { backgroundColor: "#ffffff", borderColor: "#ffb020" }]}>
        <Text style={st.labelTxt} numberOfLines={1}>{left}</Text>
      </Animated.View>
    )}
  </>);
}

const INK = "#0b3d6e";
const st = StyleSheet.create({
  sub: { fontSize: 12, color: INK, opacity: 0.8, letterSpacing: 0.4 },
  end: { position: "absolute", right: 14, width: 44, height: 44, borderRadius: 22, alignItems: "center", justifyContent: "center", backgroundColor: "rgba(255,255,255,0.55)", borderWidth: 1.5, borderColor: "rgba(255,255,255,0.9)" },
  endTxt: { fontSize: 12, fontWeight: "700", color: INK },
  label: { paddingHorizontal: 12, paddingVertical: 4, borderRadius: 14, backgroundColor: "rgba(255,255,255,0.55)", borderWidth: 1, borderColor: "rgba(255,255,255,0.95)" },
  labelTxt: { fontSize: 15, fontWeight: "800", color: INK },
  info: { position: "absolute", left: 14, right: 72, paddingHorizontal: 16, paddingVertical: 12, borderRadius: 20, backgroundColor: "rgba(255,255,255,0.82)", borderWidth: 1.5, borderColor: "rgba(255,255,255,0.95)" },
  infoTitle: { fontSize: 17, fontWeight: "800", color: INK, fontFamily: Platform.select({ ios: "HelveticaNeue-Medium", default: undefined }) },
  infoLine: { fontSize: 13, color: INK, marginTop: 3 },
  infoHint: { fontSize: 12, color: INK, opacity: 0.7, marginTop: 6 },
  looks: { position: "absolute", left: 14, right: 14, flexDirection: "row", flexWrap: "wrap", alignItems: "center", gap: 8, padding: 8, borderRadius: 22, backgroundColor: "rgba(255,255,255,0.45)", borderWidth: 1, borderColor: "rgba(255,255,255,0.9)" },
  chip: { minHeight: 36, paddingHorizontal: 14, borderRadius: 18, justifyContent: "center", backgroundColor: "rgba(255,255,255,0.6)" },
  chipOn: { backgroundColor: "#1e9be8" },
  chipTxt: { fontSize: 13, fontWeight: "700", color: INK },
});
